package alpha

import (
	"fmt"
	"os"
	"testing"
	"time"
)

func TestMain(m *testing.M) {
	fmt.Fprintln(os.Stdout, "TestMain: setting up")
	code := m.Run()
	fmt.Fprintln(os.Stdout, "TestMain: tearing down")
	os.Exit(code)
}

func TestAdd(t *testing.T) {
	if Add(1, 2) != 3 { t.Errorf("Add broken") }
}

func TestMul(t *testing.T) {
	t.Log("about to multiply")
	if Mul(3, 4) != 12 { t.Fatal("Mul broken") }
	t.Logf("multi\nline\tlog with tab")
}

func TestSkipMe(t *testing.T) {
	t.Skip("not on this platform")
}

func TestSkipNow(t *testing.T) {
	t.Log("before skip")
	t.SkipNow()
}

func TestNested(t *testing.T) {
	t.Run("Level1", func(t *testing.T) {
		t.Run("Level2", func(t *testing.T) {
			t.Run("Level3", func(t *testing.T) {
				t.Log("deep")
			})
		})
		t.Run("Level2b", func(t *testing.T) { t.Skip("skip deep") })
	})
	t.Run("Group With Spaces", func(t *testing.T) {})
	t.Run("weird/name#1", func(t *testing.T) {})
}

func TestParallel(t *testing.T) {
	for _, n := range []string{"P1", "P2", "P3"} {
		n := n
		t.Run(n, func(t *testing.T) {
			t.Parallel()
			time.Sleep(10 * time.Millisecond)
			t.Logf("parallel %s done", n)
		})
	}
}

func TestSlow(t *testing.T) {
	time.Sleep(1100 * time.Millisecond)
}

func Example() {
	fmt.Println(Add(1, 2))
	// Output: 3
}

func ExampleMul() {
	fmt.Println(Mul(2, 5))
	// Output: 10
}

func BenchmarkAdd(b *testing.B) {
	for i := 0; i < b.N; i++ { Add(i, i) }
}

func BenchmarkRev(b *testing.B) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ { Rev("hello world") }
}

func FuzzRev(f *testing.F) {
	f.Add("abc")
	f.Fuzz(func(t *testing.T, s string) {
		if Rev(Rev(s)) != s { t.Fatalf("not idempotent: %q", s) }
	})
}
EOF
